 public void AddBullet(Vector3 p,Vector3 velocity,bool friendly,int style,float damage=1,float radius=.17f,bool homing=false,float curve=0,int pierce=0,int kind=0){if(Bullets.Count>=3400)return;if(!friendly)enemyRoundsSpawned++;Bullets.Add(new Round{pos=p,prev=p,velocity=velocity,friendly=friendly,style=style,damage=damage,radius=radius,life=friendly?(kind==3?1.0f:2.6f):10,homing=homing,curve=curve,pierce=pierce,kind=kind});}
