 public Hostile SpawnEnemy(int kind,Vector3 pos,int pattern){var go=Art.Model(kind==0?"Drone":kind==1?"Interceptor":kind==2?"Gunship":"Leviathan",null);go.transform.position=pos;float scale=kind==0?.8f:kind==1?.7f:kind==2?.95f:.45f;go.transform.localScale=Vector3.one*scale;go.transform.rotation=Quaternion.Euler(0,180,0);float hp=(kind==0?12:kind==1?26:kind==2?80:125)*(1+Stage*.16f);var e=new Hostile{go=go,pos=pos,origin=pos,kind=kind,pattern=pattern,hp=hp*(1+EndlessLoop*.3f),maxHp=hp*(1+EndlessLoop*.3f),fire=1.5f+UnityEngine.Random.value,phase=UnityEngine.Random.value*6,renderers=go.GetComponentsInChildren<Renderer>()};e.baseColors=RendererColors(e.renderers);Enemies.Add(e);return e;}
