 void UpdateEnemies(float dt){for(int i=Enemies.Count-1;i>=0;i--){var e=Enemies[i];if(!e.go)continue;e.age+=dt;e.fire-=dt;e.flash=Mathf.Max(0,e.flash-dt);e.recoil=Mathf.MoveTowards(e.recoil,0,dt*1.7f);if(e.owner!=null){TickBossModule(e,dt);continue;}if(e.boss){e.pos.z=Mathf.MoveTowards(e.pos.z,8.2f,dt*3);e.pos.x=Mathf.Sin(e.age*.35f)*5.7f;int phase=e.hp/e.maxHp>.67f?0:e.hp/e.maxHp>.33f?1:2;if(phase!=bossPhase){bossPhase=phase;Burst(e.pos,24,2);if(phase>0){Sound("Warning",.7f);warningClock=1.5f;CancelBullets(false);}}TickBossEncounter(e,phase,dt);}
 else {float speed=e.elite?(e.age<3?3.8f:e.age<19?.25f:4.5f):e.kind>=2?2.1f:e.kind==1?4.6f:5.6f;e.pos.z-=dt*speed;e.pos.x=e.origin.x+Mathf.Sin(e.age*(e.pattern==5?2:1.4f)+e.phase)*(e.pattern==0?.4f:e.pattern==6?2.8f:e.pattern==4?2.2f:1.1f);UpdateWeaponTell(e);if(e.fire<=0&&e.pos.z<13&&e.pos.z>PlayerPos.z+1){EnemyAttack(e);FinishWeaponTell(e);e.fire=e.kind>=2?1.3f:2.2f;}if(e.pos.z<-15){Destroy(e.go);Enemies.RemoveAt(i);continue;}}
