 if(invuln<=0&&(e.pos-PlayerPos).sqrMagnitude<(e.boss?5.5f:e.kind>=2?1.3f:.65f))HitPlayer();
 }}
 void EnemyAttack(Hostile e){if(e.elite){for(int j=0;j<16;j++){float a=e.age*.4f+j*Mathf.PI*2/16;AddBullet(e.pos,new Vector3(Mathf.Sin(a),0,Mathf.Cos(a))*4.5f*DifficultySpeed,false,2);}}Vector3 aim=((e.aimReady?e.lockedAim:PlayerPos)-e.pos).normalized;aim.y=0;float speed=(e.kind>=2?7:6)*DifficultySpeed;int n=e.kind==0?1:e.kind==1?3:5;for(int k=0;k<n;k++){float a=(k-(n-1)*.5f)*11;AddBullet(e.pos+Vector3.back*.5f,Quaternion.Euler(0,a,0)*aim*speed,false,1);}}
