 public static float SegmentDistance(Vector3 point,Vector3 a,Vector3 b){Vector3 ab=b-a;float t=Mathf.Clamp01(Vector3.Dot(point-a,ab)/Mathf.Max(.000001f,ab.sqrMagnitude));return Vector3.Distance(point,a+ab*t);}
 void UpdateBullets(float dt){pendingDamage.Clear();bool hurt=false;for(int i=Bullets.Count-1;i>=0;i--){Round b=Bullets[i];b.prev=b.pos;b.age+=dt;if(b.curve!=0)b.velocity=Quaternion.Euler(0,b.curve*dt,0)*b.velocity;if(b.homing&&b.age>(b.kind==4?.16f:.025f)&&Enemies.Count>0){Hostile target=null;float d=float.MaxValue;foreach(var e in Enemies){float dd=(e.pos-b.pos).sqrMagnitude;if(hunters>0&&e.kind>=2)dd*=.55f;if(dd<d){d=dd;target=e;}}if(target!=null){Vector3 desired=(target.pos-b.pos).normalized*24;b.velocity=Vector3.Lerp(b.velocity,desired,dt*5);}}
 b.pos+=b.velocity*dt*(!b.friendly&&Ship==2&&SkillTime>0?.32f:1);b.life-=dt;bool dead=b.life<=0||Mathf.Abs(b.pos.x)>28||b.pos.z<-18||b.pos.z>27;
 if(!dead&&b.friendly){for(int j=Enemies.Count-1;j>=0;j--){var e=Enemies[j];float radius=e.boss?2.65f:e.kind==3?1.8f:e.kind==2?1.35f:e.kind==1?.75f:.67f;if(e!=b.lastHit&&SegmentDistance(e.pos,b.prev,b.pos)<radius+b.radius){if(pendingDamage.ContainsKey(e))pendingDamage[e]+=b.damage;else pendingDamage[e]=b.damage;WeaponImpact(b,e);if(b.pierce>0){b.pierce--;b.lastHit=e;}else dead=true;break;}}}
 else if(!dead&&!b.friendly){float d=SegmentDistance(PlayerPos,b.prev,b.pos);if(d<.18f+b.radius){dead=true;if(invuln<=0)hurt=true;}else if(d<.9f&&!b.grazed){b.grazed=true;Grazes++;Score+=25;Energy=Mathf.Min(100,Energy+1.8f+upgradeEnergy*.6f);Burst(PlayerPos,2,0,.18f);}}
 if(dead)Bullets.RemoveAt(i);else Bullets[i]=b;}foreach(var pair in pendingDamage)if(Enemies.Contains(pair.Key))DamageEnemy(pair.Key,pair.Value);if(hurt)HitPlayer();}
 public void DamageEnemy(Hostile e,float damage){if(!Enemies.Contains(e))return;damage*=BossDamageScale(e);e.hp-=damage;OnArmorImpact(e,damage);if(e.hp>0)return;BossModuleDestroyed(e);Kills++;int points=e.boss?20000:e.kind==3?1000:e.kind==2?650:e.kind==1?250:120;RewardElite(e);Combo++;MaxCombo=Mathf.Max(Combo,MaxCombo);comboClock=4;Score+=points*Mathf.Min(10,1+Combo/8);Energy=Mathf.Min(100,Energy+(e.boss?30:2+upgradeEnergy));OnTargetDestroyed(e,points);
 if(e.boss){foreach(var node in Enemies.ToArray())if(node.owner==e){Destroy(node.go);Enemies.Remove(node);}ClearBossEncounter();Score+=Mathf.Max(0,MaxHull-stageDamage)*1000;stageEndClock=4.2f;CancelBullets(true);Bombs=Mathf.Min(5,Bombs+1);Hull=Mathf.Min(MaxHull,Hull+1);pilotSpeaker=(Ship+1)%3;RadioName=PilotNames[pilotSpeaker]+" / 小队通讯";RadioText=new[]{"要塞沉默了。撤离船队已通过防线，我们前往城市。","雷暴正在消散。最后一个指令源在轨道上——准备爬升。","收到人类识别码。天环停止攻击……我们把天空还给了所有人。"}[Stage];dialogClock=8;Boss=null;}
 else if(e.kind==3||Kills%11==0)SpawnSupply(e.pos,e.kind==3?0:Kills%22==0?1:2);
 Enemies.Remove(e);Destroy(e.go);
 }
 public void HitPlayer(){if(invuln>0||State!=FlightState.Playing)return;Hull--;stageDamage++;campaignDamage++;Combo=0;invuln=2.5f;shake=.8f;hurtEdge=.8f;audioDuck=.4f;Sound("Hit",.9f);Burst(PlayerPos,36,1,.8f);for(int i=Bullets.Count-1;i>=0;i--)if(!Bullets[i].friendly&&(Bullets[i].pos-PlayerPos).sqrMagnitude<5)Bullets.RemoveAt(i);if(Hull>0)PlayPilotBark(Hull<=2?"danger":"hurt",Ship,Hull<=2?100:20);if(Hull<=0){State=FlightState.Defeat;World.Scrolling=false;Post.Flash=0;FinishScore();Sound("Bomb");}}
 public void UseBomb(){if(State!=FlightState.Playing||Bombs<=0||stageEndClock>0||NovaActive)return;Bombs--;invuln=2.5f;bombFlash=.055f;PlayPilotBark("bomb",Ship,75);BeginNova();CancelBullets(true);}
 public void UseOverdrive(){if(State!=FlightState.Playing||Energy<100||Overdrive>0||stageEndClock>0)return;Energy=0;Overdrive=8+upgradeEnergy;invuln=1;CancelBullets(true);Sound("Overdrive");PlayPilotBark("overdrive",Ship,80);cutinClock=1.65f;cutinIsOverdrive=true;Toast("天翼机甲展开 · OVERDRIVE",3);Shockwave(PlayerPos,Art.Cyan,10);bombFlash=.2f;shake=.3f;}
 void CancelBullets(bool reward){for(int i=Bullets.Count-1;i>=0;i--){if(Bullets[i].friendly)continue;if(reward)Score+=10;if(i%4==0)Burst(Bullets[i].pos,1,0,.25f);Bullets.RemoveAt(i);}}
 public void SpawnSupply(Vector3 p,int kind){var go=new GameObject("Supply");var color=kind==0?new Color(.15f,1,.5f):kind==1?Art.Orange:Art.Cyan;var core=Art.Primitive(go.transform,"Module",Vector3.zero,Vector3.one*.55f,Art.Mat("supply"+kind,color,true),PrimitiveType.Cube);core.transform.rotation=Quaternion.Euler(25,45,25);Art.Ring(go.transform,.65f,color,.055f);Supplies.Add(new Supply{go=go,pos=p,kind=kind});}
 void UpdateSupplies(float dt){for(int i=Supplies.Count-1;i>=0;i--){var p=Supplies[i];p.age+=dt;Vector3 to=PlayerPos-p.pos;p.pos+=to.sqrMagnitude<16?to.normalized*dt*9:Vector3.back*dt*3;p.go.transform.position=p.pos;p.go.transform.rotation=Quaternion.Euler(0,p.age*75,0);if(to.sqrMagnitude<1.1f){if(p.kind==0)Hull=Mathf.Min(MaxHull,Hull+1);else if(p.kind==1)Bombs=Mathf.Min(5,Bombs+1);else Energy=Mathf.Min(100,Energy+25);Score+=500;Sound("Pickup");Burst(p.pos,18,0);Destroy(p.go);Supplies.RemoveAt(i);}else if(p.pos.z<-15){Destroy(p.go);Supplies.RemoveAt(i);}}}
 public void AddBeam(float x){if(Mathf.Abs(x)>11)return;var o=new GameObject("Telegraphed beam");var l=Art.Line(o.transform,"Laser",new[]{new Vector3(x,1,-13),new Vector3(x,1,17)},Art.Orange,.06f);Beams.Add(new Beam{x=x,go=o,line=l,duration=3.1f});}
 void UpdateBeams(float dt){for(int i=Beams.Count-1;i>=0;i--){var b=Beams[i];b.age+=dt;if(b.age>1.75f){if(!b.fired){b.fired=true;Sound("Overdrive",.35f);}b.line.startWidth=b.line.endWidth=.62f;if(Mathf.Abs(PlayerPos.x-b.x)<.4f&&invuln<=0)HitPlayer();}else b.line.startWidth=b.line.endWidth=.04f+Mathf.Sin(b.age*25)*.016f;if(b.age>b.duration){Destroy(b.go);Beams.RemoveAt(i);}}}
 public void Burst(Vector3 p,int count,int style,float size=1){for(int i=0;i<count&&sparks.Count<1500;i++){float life=UnityEngine.Random.Range(.2f,.85f)*(style==1?1.4f:1);sparks.Add(new Spark{pos=p,velocity=UnityEngine.Random.insideUnitSphere*UnityEngine.Random.Range(1,7)*size,life=life,max=life,size=UnityEngine.Random.Range(.06f,.25f)*size,style=style==1?(i%4==0?4:i%3==0?5:3):style==2?2:style==3?3:0});}}
 void UpdateSparks(float dt){for(int i=sparks.Count-1;i>=0;i--){var s=sparks[i];s.life-=dt;if(s.life<=0){sparks.RemoveAt(i);continue;}s.pos+=s.velocity*dt;s.velocity*=1-dt*1.7f;sparks[i]=s;}}
 void LateUpdate(){if(shotMats==null||State==FlightState.Hangar)return;enemyRims.Clear();foreach(var list in draws)list.Clear();foreach(var b in Bullets){if(b.friendly&&b.kind>0){DrawWeaponRound(b);continue;}Vector3 scale=b.friendly?new Vector3(b.radius*1.3f,b.radius*1.3f,b.homing?.65f:1.15f):Vector3.one*b.radius*2;Quaternion rot=Quaternion.LookRotation(b.velocity.sqrMagnitude>.01f?b.velocity:Vector3.forward);draws[b.style].Add(Matrix4x4.TRS(b.pos,rot,scale));if(!b.friendly){enemyRims.Add(Matrix4x4.TRS(b.pos,Quaternion.identity,Vector3.one*b.radius*2.65f));draws[3].Add(Matrix4x4.TRS(b.pos+Vector3.up*.03f,Quaternion.identity,Vector3.one*b.radius*.95f));}}
 foreach(var s in sparks){float k=s.life/s.max;float size=s.size*(s.style==4?1+(1-k)*3:k);Quaternion rotation=s.style==4?Cam.transform.rotation:s.style==3&&s.velocity.sqrMagnitude>.01f?Quaternion.LookRotation(s.velocity):Quaternion.Euler(s.life*200,s.life*120,0);Vector3 stretch=s.style==3?new Vector3(.42f,.42f,2.8f):Vector3.one;draws[s.style].Add(Matrix4x4.TRS(s.pos,rotation,stretch*size*(s.style==4?3:1)));}
 for(int offset=0;offset<enemyRims.Count;offset+=1023){int n=Mathf.Min(1023,enemyRims.Count-offset);enemyRims.CopyTo(offset,matrices,0,n);Graphics.DrawMeshInstanced(sphere,0,projectileRim,matrices,n,null,ShadowCastingMode.Off,false,0,Cam);}
 for(int i=0;i<draws.Length;i++){var list=draws[i];for(int offset=0;offset<list.Count;offset+=1023){int n=Mathf.Min(1023,list.Count-offset);list.CopyTo(offset,matrices,0,n);Graphics.DrawMeshInstanced(i==4?quad:i==5?cube:sphere,0,shotMats[i],matrices,n,null,ShadowCastingMode.Off,false,0,Cam);}}}

 void ApplyViewport(){if(!Cam)return;float aspect=Screen.width/(float)Mathf.Max(1,Screen.height);const float desired=16f/9;if(aspect>desired){float w=desired/aspect;Cam.rect=new Rect((1-w)/2,0,w,1);}else{float h=aspect/desired;Cam.rect=new Rect(0,(1-h)/2,1,h);}}
 void UpdateCamera(float dt){Cam.orthographicSize=Mathf.Lerp(Cam.orthographicSize,12.8f,dt*3);var target=cameraBase+new Vector3(PlayerPos.x*.06f,0,0);if(ShakeEnabled)target+=UnityEngine.Random.insideUnitSphere*shake*.35f;Cam.transform.position=target;Post.Flash=bombFlash;Post.Damage=hurtEdge;Post.Intensity=Overdrive>0?1:.6f;}
 public void BeginEndless(){BeginRun();Endless=true;}
 void CompleteStage(){if((Stage>=2||Practice)&&!Endless){State=FlightState.Victory;World.Scrolling=false;ChangeMusic(3);FinishScore();return;}if(!Endless)Unlocked=Mathf.Max(Unlocked,Stage+1);else if(Stage==2)EndlessLoop++;RollUpgrades();SaveSettings();State=FlightState.Upgrade;World.Scrolling=false;UpgradePick=-1;}
 public void ApplyUpgrade(int n){if(State!=FlightState.Upgrade)return;UpgradePick=n;ApplyFeatureUpgrade(n);Stage=Endless?(Stage+1)%3:Stage+1;BeginStage();Sound("Pickup");}
 void FinishScore(){RewardPilot();HighScore=Mathf.Max(HighScore,Score);if(State==FlightState.Victory&&!Practice)Unlocked=2;SaveSettings();}
}
